/*
 * A027396  Number of labeled servers of dimension 9.
 * https://oeis.org/A027396
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 7, u64 n <= 13, u128 n <= 25,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) = coefficient of x^n in
 *   exp( Σ_{i=1..9} ((1+x)^i - 1)/i )
 *
 * The sequence can be generated by the recurrence
 *   a_0 = 1
 *   a_m = Σ_{k=1}^{min(9,m)} g_k * C(m-1, k-1) * a_{m-k}
 *
 *   where g_k = ( Σ_{i=k}^{9} binom(i,k)/i ) * k!
 *   is an integer constant:
 *     g_1 =   9
 *     g_2 =  36
 *     g_3 = 168
 *     g_4 = 756
 *     g_5 =3024
 *     g_6 =10080
 *     g_7 =25920
 *     g_8 =45360
 *     g_9 =40320
 *
 *   C(n,r) is the ordinary binomial coefficient.
 *
 * The recurrence uses only integer arithmetic, so the result
 * is exact for any integer type that the build supports.
 */
#include <stdlib.h>
#include <stddef.h>

/* --------------------------------------------------------------------- */
/*   Helper: compute ordinary binomial coefficient C(n,r) for r <= 8     */
static inline seq_t
binom_small(idx_t n, idx_t r)
{
    if (r > n) return 0;
    if (r > n - r) r = n - r;          /* use symmetry          */
    seq_t res = 1;
    for (idx_t i = 1; i <= r; ++i) {
        /* multiply first, then divide by the small integer i      */
        res = (res * (n - r + i)) / i;
    }
    return res;
}

/* --------------------------------------------------------------------- */
/*   Array to cache previously computed values                         */
static seq_t *cache = NULL;      /* static cache of a(n) values    */
static idx_t  cache_len = 0;     /* highest index computed so far */

/* Integer constants g_k described above.  Index 0 is unused. */
static const seq_t G[10] = {
    0,     /* unused */
    9,      /* g_1  */
    36,     /* g_2  */
    168,    /* g_3  */
    756,    /* g_4  */
    3024,   /* g_5  */
    10080,  /* g_6  */
    25920,  /* g_7  */
    45360,  /* g_8  */
    40320   /* g_9  */
};

/* --------------------------------------------------------------------- */
seq_t
a(idx_t n)
{
    /* handle the trivial case n==0 immediately */
    if (n == (idx_t)0)
    {
        static seq_t one = 1;
        return one;
    }

    /* allocate and initialise the cache if it does not exist yet   */
    if (cache == NULL)
    {
        cache = (seq_t *)malloc(sizeof(seq_t));
        if (cache == NULL) exit(1);
        cache[0] = 1;                /* a(0) = 1   */
        cache_len = 0;
    }

    /* resize cache if necessary */
    if (cache_len < n)
    {
        size_t newsize = (size_t)(n + 1);
        seq_t *new_cache = (seq_t *)realloc(cache, newsize * sizeof(seq_t));
        if (new_cache == NULL) exit(1);
        cache = new_cache;

        /* compute missing terms up to a(n) */
        for (idx_t m = cache_len + 1; m <= n; ++m)
        {
            seq_t sum = 0;
            idx_t kmax = (m < (idx_t)10 ? m : (idx_t)9);
            idx_t nVar = m - 1;
            for (idx_t k = 1; k <= kmax; ++k)
            {
                seq_t bin = binom_small(nVar, k - 1);
                /* multiply in the order G[k] * bin * a[m-k]   */
                sum += G[k] * bin * cache[m - k];
            }
            cache[m] = sum;
        }
        cache_len = n;
    }

    return cache[n];
}
